\title{A Combinatorics--Analysis Bridge for the Isolation Lemma:\\
Exact Counts and Asymptotic Density of Strict-Minimum Assignments}
\author{Aristotle}
\date{2026-07-13}

\begin{document}
\maketitle

\begin{abstract}
The Isolation Lemma asserts that random weights on the elements of a combinatorial
structure single out a unique minimum-weight member with good probability. We study its
sharpest special case---the \emph{singleton hypergraph} on $n$ vertices---where an
assignment is \emph{isolating} precisely when one vertex is a strict minimum. We prove an
exact enumerative identity: among the $d^n$ weight assignments valued in $\{0,\dots,d-1\}$,
the number that are isolating equals $n\sum_{j=0}^{d-1} j^{\,n-1}$, matching the
Faber--Harris lower bound term for term. We then build a bridge from this combinatorial
identity to real analysis, showing that the \emph{density} of isolating assignments,
$R(n,d)=n\sum_{j<d}j^{\,n-1}/d^{\,n}$, tends to $1$ as $d\to\infty$ for every fixed
$n\ge 1$. The proof is elementary and quantitative: a discrete Mean-Value inequality
$(k+1)x^{k}\le (x+1)^{k+1}-x^{k+1}\le (k+1)(x+1)^{k}$, summed telescopically, traps the
power sum in the fence $d^{\,n}-n\,d^{\,n-1}\le n\sum_{j<d}j^{\,n-1}\le d^{\,n}$, whence
$1-n/d\le R(n,d)\le 1$ and a squeeze yields the limit. Probabilistically: when the $n$
weights are drawn independently and uniformly, the probability of a strict minimum tends to
$1$, so ties are asymptotically negligible. We record a min$\leftrightarrow$max duality
producing a second symmetric extremal witness (the co-singleton family), delimit the
failure of a naive general tightness conjecture, and outline sharpenings toward a
quantitative Berry--Esseen form.
\end{abstract}

\section{Introduction}

\subsection{Background}
The \emph{Isolation Lemma} of Mulmuley, Vazirani and Vazirani is a workhorse of randomized
computation. Given a nonempty family $\mathcal{F}$ of subsets of a ground set of $n$
elements, assign each element an independent uniform weight from $\{1,\dots,W\}$; with
probability at least $1-n/W$ there is a \emph{unique} member of $\mathcal{F}$ of minimum
total weight. Randomness breaks ties among exponentially many competing structures using
only polynomially many random bits. This mechanism underlies randomized parallel algorithms
for matching, the Valiant--Vazirani reduction from general to unique satisfiability, and
numerous derandomization and hardness results.

We isolate the sharpest and most transparent case, the \emph{singleton hypergraph}, and
answer two quantitative questions completely---first with an exact finite count, then with
an asymptotic density that connects combinatorics to real analysis.

\subsection{Contributions}
\begin{enumerate}[label=(\arabic*)]
\item \textbf{Exact count} (Theorem~\ref{thm:count}). For the singleton hypergraph on $n$
vertices with weights in $\{0,\dots,d-1\}$ and zero offset, the number of isolating
assignments is exactly $n\sum_{j=0}^{d-1} j^{\,n-1}$.
\item \textbf{Asymptotic density bridge} (Theorem~\ref{thm:density}). For every fixed
$n\ge 1$, the density of isolating assignments tends to $1$ as $d\to\infty$.
\item \textbf{Quantitative fence} (Proposition~\ref{prop:fence}). $1-n/d\le R(n,d)\le 1$.
\item \textbf{Structural remarks} (Section~\ref{sec:struct}). A min$\leftrightarrow$max
duality yields the co-singleton family as a second symmetric extremal witness; a single
all-encompassing edge refutes a naive general-tightness conjecture.
\end{enumerate}

\section{Definitions}

Throughout, $n$ (the number of vertices) and $d$ (the size of the weight range) are natural
numbers. A \emph{weight assignment} is a function $w:\{0,\dots,n-1\}\to\{0,\dots,d-1\}$;
there are $d^n$ of them.

\begin{definition}[Hypergraph, inclusion-free]
A \emph{hypergraph} on $n$ vertices is a finite family $H$ of subsets (edges) of
$\{0,\dots,n-1\}$. It is \emph{inclusion-free} (a Sperner family / antichain) if for all
$S,T\in H$ with $S\subseteq T$ we have $S=T$.
\end{definition}

\begin{definition}[Singleton hypergraph]
The \emph{singleton hypergraph} is the family of all one-element edges
$\{\{i\}:0\le i<n\}$. It is inclusion-free.
\end{definition}

\begin{definition}[Strict minimum / isolating]
A weight assignment $w$ \emph{has a strict minimum} if there is a vertex $i$ with
$w(i)<w(j)$ for all $j\ne i$. For the singleton hypergraph the minimum-weight edge is unique
exactly when $w$ has a strict minimum; such assignments are \emph{isolating}. We write
\[
\Iso(n,d)=\{\,w \mid w \text{ has a strict minimum}\,\},\qquad I(n,d)=\#\Iso(n,d).
\]
\end{definition}

\begin{definition}[Strict-min-at-$i$ set]
For a vertex $i$, let $\Min_i(n,d)=\{\,w\mid \forall j\ne i,\ w(i)<w(j)\,\}$.
\end{definition}

\begin{definition}[Isolation density]
The \emph{isolation density} is $R(n,d)=I(n,d)/d^{\,n}\in[0,1]$. Interpreting $w$ as $n$
independent uniform draws from $\{0,\dots,d-1\}$, $R(n,d)$ is the probability that $w$ has a
strict minimum.
\end{definition}

\section{The exact count}

\begin{lemma}[Fiber count]\label{lem:fiber}
Fix a vertex $i$ and a value $m\in\{0,\dots,d-1\}$. The number of assignments with $w(i)=m$
and $w(j)>m$ for all $j\ne i$ is $(d-1-m)^{\,n-1}$.
\end{lemma}
\begin{proof}
The value at $i$ is fixed to $m$; each of the other $n-1$ vertices must take one of the
$d-1-m$ values strictly above $m$. Independence over vertices gives $(d-1-m)^{\,n-1}$.
\end{proof}

\begin{lemma}[Per-vertex count]\label{lem:pervertex}
For every vertex $i$,
\[
\#\Min_i(n,d)=\sum_{m=0}^{d-1}(d-1-m)^{\,n-1}=\sum_{j=0}^{d-1} j^{\,n-1},
\]
independent of $i$.
\end{lemma}
\begin{proof}
Partition $\Min_i(n,d)$ by the value $m=w(i)$. By Lemma~\ref{lem:fiber} the block for $m$
has size $(d-1-m)^{\,n-1}$. Summing over $m$ and reindexing $j=d-1-m$ gives
$\sum_{j=0}^{d-1}j^{\,n-1}$, independent of $i$.
\end{proof}

\begin{lemma}[Disjoint decomposition]\label{lem:disjoint}
The sets $\Min_i(n,d)$, $0\le i<n$, are pairwise disjoint with union $\Iso(n,d)$; hence
$I(n,d)=\sum_{i=0}^{n-1}\#\Min_i(n,d)$.
\end{lemma}
\begin{proof}
A strict minimum, when it exists, is unique: two distinct strict minima $i,i'$ would give
$w(i)<w(i')$ and $w(i')<w(i)$, absurd. Thus the $\Min_i$ are disjoint. An assignment lies in
some $\Min_i$ iff it has a strict minimum, i.e.\ iff it is in $\Iso(n,d)$. Cardinality of a
disjoint union is the sum of cardinalities.
\end{proof}

\begin{theorem}[Exact isolation count]\label{thm:count}
For all $n,d$,
\[
I(n,d)=n\sum_{j=0}^{d-1} j^{\,n-1}.
\]
\end{theorem}
\begin{proof}
Combine Lemmas~\ref{lem:pervertex} and \ref{lem:disjoint}:
$I(n,d)=\sum_{i=0}^{n-1}\sum_{j=0}^{d-1}j^{\,n-1}=n\sum_{j=0}^{d-1}j^{\,n-1}$.
\end{proof}

\begin{remark}[Faber--Harris tightness]
The right-hand side is precisely the Faber--Harris lower bound term for the number of
isolating assignments; the singleton hypergraph meets this bound with equality and is thus
an exact extremal witness.
\end{remark}

\begin{example}
$I(2,2)=2(0^1+1^1)=2$ out of $4$ (the orderings $(0,1),(1,0)$);
$I(3,4)=3(0^2+1^2+2^2+3^2)=42$ out of $64$.
\end{example}

\section{The analytic bridge: density tends to one}

\begin{lemma}[Discrete Mean-Value bounds]\label{lem:mvt}
For every real $x\ge 0$ and integer $k\ge 0$,
\[
(k+1)\,x^{k}\ \le\ (x+1)^{k+1}-x^{k+1}\ \le\ (k+1)\,(x+1)^{k}.
\]
\end{lemma}
\begin{proof}
Both follow by induction on $k$ or from the binomial theorem. Since
$(x+1)^{k+1}-x^{k+1}=\sum_{r=0}^{k}\binom{k+1}{r}x^{r}$ has nonnegative terms, keeping only
$r=k$ gives the lower bound $(k+1)x^{k}$. For the upper bound, use
$\binom{k+1}{r}\le(k+1)\binom{k}{r}$ ($0\le r\le k$) to get
$\sum_{r=0}^{k}\binom{k+1}{r}x^{r}\le(k+1)\sum_{r=0}^{k}\binom{k}{r}x^{r}=(k+1)(x+1)^{k}$.
These are the discrete analogues of $\tfrac{d}{dt}t^{k+1}=(k+1)t^{k}$ at the two endpoints
of the unit step.
\end{proof}

\begin{proposition}[Telescoping sum fence]\label{prop:tele}
For all integers $d\ge 0$, $k\ge 0$ (over $\R$),
\[
(k+1)\sum_{j=0}^{d-1} j^{\,k}\ \le\ d^{\,k+1}
\qquad\text{and}\qquad
d^{\,k+1}\ \le\ (k+1)\sum_{j=0}^{d-1} j^{\,k}+(k+1)\,d^{\,k}.
\]
\end{proposition}
\begin{proof}
Telescoping, $d^{\,k+1}=\sum_{j=0}^{d-1}\big((j+1)^{k+1}-j^{k+1}\big)$. The lower bound of
Lemma~\ref{lem:mvt} at $x=j$ gives $d^{\,k+1}\ge(k+1)\sum_{j<d}j^{\,k}$; the upper bound
gives $d^{\,k+1}\le(k+1)\sum_{j=1}^{d}j^{\,k}=(k+1)\sum_{j<d}j^{\,k}+(k+1)d^{\,k}$.
\end{proof}

\begin{proposition}[Quantitative fence]\label{prop:fence}
Writing $n=k+1$, for all $d\ge 1$,
\[
d^{\,n}-n\,d^{\,n-1}\ \le\ n\sum_{j=0}^{d-1} j^{\,n-1}\ \le\ d^{\,n},
\qquad\text{i.e.}\qquad
1-\frac{n}{d}\ \le\ R(n,d)\ \le\ 1.
\]
\end{proposition}
\begin{proof}
Set $k=n-1$ in Proposition~\ref{prop:tele}: the first inequality is the upper wall and the
second rearranges to the lower wall $d^{\,n}-n\,d^{\,n-1}\le n\sum_{j<d}j^{\,n-1}$. Dividing
by $d^{\,n}$ and using $I(n,d)=n\sum_{j<d}j^{\,n-1}$ (Theorem~\ref{thm:count}) gives
$1-n/d\le R(n,d)\le 1$.
\end{proof}

\begin{theorem}[Isolation density tends to one]\label{thm:density}
For every fixed integer $n\ge 1$,
\[
R(n,d)=\frac{I(n,d)}{d^{\,n}}=\frac{n\sum_{j=0}^{d-1} j^{\,n-1}}{d^{\,n}}
\ \xrightarrow[d\to\infty]{}\ 1.
\]
Equivalently, when the $n$ weights are drawn independently and uniformly from
$\{0,\dots,d-1\}$, the probability that $w$ has a strict minimum tends to $1$.
\end{theorem}
\begin{proof}
With $n$ fixed, the fences $1-n/d\to 1$ and $1\to 1$ sandwich $R(n,d)$ by
Proposition~\ref{prop:fence}; the squeeze theorem gives $R(n,d)\to 1$.
\end{proof}

\begin{corollary}
$R(5,1000)\ge 0.995$ and $R(5,10^6)\ge 1-5\times10^{-6}$.
\end{corollary}

\begin{remark}
Theorem~\ref{thm:density} pins the normalized power sum
$\tfrac{1}{d^n}\sum_{j<d}j^{\,n-1}\to 1/n=\int_0^1 x^{\,n-1}\,dx$, so the exact
combinatorial identity becomes a statement of elementary analysis in the limit.
\end{remark}

\section{Structural remarks and the limits of tightness}\label{sec:struct}

\paragraph{Min--max duality.} The reflection $v\mapsto (d-1)-v$ exchanges strict minima with
strict maxima. Hence the \emph{co-singleton hypergraph} (edges of size $n-1$, so a
minimum-weight edge corresponds to a strictly largest vertex) also attains the Faber--Harris
bound exactly with zero offset and has density $\to 1$. The bound thus has two symmetric
extremal witnesses: singletons and their complements.

\paragraph{Failure of naive general tightness.} It is false that every inclusion-free
hypergraph attains $n\sum_{j<d}j^{\,n-1}$ for some real offset. The single-edge hypergraph
whose edge is the whole vertex set makes \emph{every} assignment isolating, giving count
$d^{\,n}$ for all offsets---already $4>2$ at $n=d=2$. Covering antichains such as
$\{\{0,1\},\{0,2\}\}$ also overshoot for every offset. A general theorem quantifying failure
over all real offsets requires reducing the continuum of offsets to finitely many
order-types.

\paragraph{Toward a characterization.} For $n=3$, exactly the singletons and co-singletons
reach the bound in the offset-free problem; a conjectural criterion is vertex-transitivity
plus ``sum-symmetry.'' A clean characterization, and the status of intermediate $k$-uniform
complete families, remain open.

\section{Algorithms}
\begin{itemize}
\item \textbf{Exact count.} Return $n\sum_{j=0}^{d-1}j^{\,n-1}$ in $O(d\log n)$ arithmetic
operations, versus $O(n\,d^n)$ for brute force.
\item \textbf{Brute-force verification.} Enumerate all $d^n$ assignments and count strict
minima, in $O(n\,d^n)$, to cross-check on small inputs.
\item \textbf{Convergence certificate.} Given $\varepsilon$, return
$d=\lceil n/\varepsilon\rceil$; Proposition~\ref{prop:fence} certifies
$R(n,d)\ge 1-\varepsilon$.
\end{itemize}

\section{Applications}
\begin{itemize}
\item \textbf{Sizing random tie-breaking:} $d\ge n/\varepsilon$ guarantees isolation
confidence $1-\varepsilon$ for the singleton and co-singleton cases.
\item \textbf{Sanity oracle:} the closed form $n\sum_{j<d}j^{\,n-1}$ validates empirical
estimates of isolation probability.
\item \textbf{Extremal benchmark:} the singleton family calibrates how far other families
sit above the bound.
\end{itemize}

\section{Future directions}
\begin{itemize}
\item \textbf{Second-order term.} Sharpen the fence to
$1-R(n,d)=(n-1)/(2d)+O(1/d^2)$ via Euler--Maclaurin corrections to Faulhaber's formula.
\item \textbf{General hypergraphs.} Does a density limit hold for arbitrary inclusion-free
hypergraphs, connecting Sperner theory to a $0$--$1$ law?
\item \textbf{Probabilistic formalization.} Recast Theorem~\ref{thm:density} in terms of
uniform product measures.
\item \textbf{Joint limit in $(n,d)$.} For $n=n(d)\to\infty$, locate the phase transition
suggested by the fence $1-n/d$ near $n\asymp d$.
\item \textbf{Extremal characterization.} Characterize antichains attaining the offset-free
bound and study the invariant $\mathrm{excess}(H)=\min_f\#\mathrm{isolating}(H,f)-B(n,d)$.
\end{itemize}

\section{Conclusion}
For the singleton hypergraph, the number of isolating weight assignments in
$\{0,\dots,d-1\}^n$ is exactly $n\sum_{j=0}^{d-1}j^{\,n-1}$, meeting the Faber--Harris bound
with equality; and the density is trapped in $[1-n/d,\,1]$ and converges to $1$. The passage
from exact count to limit is a self-contained telescoping sandwich on a discrete Mean-Value
inequality---a compact bridge from finite combinatorics to real analysis: give randomness
enough room, and ties disappear.

\end{document}

