"""Exact power-sum count vs. Riemann-sum limit: pinning the sum to 1/n.

Demonstrates that the normalized power sum (1/d^n) * sum_{j<d} j^(n-1) converges
to the analytic value  integral_0^1 x^(n-1) dx = 1/n,  which is exactly why the
isolation density R(n,d) = n * (that sum) tends to 1.
"""

from __future__ import annotations


def normalized_power_sum(n: int, d: int) -> float:
    """Return (1/d^n) * sum_{j=0}^{d-1} j^(n-1)."""
    return sum(j ** (n - 1) for j in range(d)) / (d ** n)


def analytic_limit(n: int) -> float:
    """Return the limit  integral_0^1 x^(n-1) dx = 1/n."""
    return 1.0 / n


def main() -> None:
    for n in (1, 2, 3, 4, 6):
        print(f"n = {n}:  analytic limit 1/n = {analytic_limit(n):.6f}")
        for d in (10, 100, 1000, 10000):
            approx = normalized_power_sum(n, d)
            err = abs(approx - analytic_limit(n))
            print(f"   d={d:>6}  normalized sum={approx:.6f}  |err|={err:.2e}")
        print()


if __name__ == "__main__":
    main()

