function EXACT_ISOLATING_COUNT(n, d):
    if n <= 0 or d <= 0: return 0
    S <- 0
    for j from 0 to d-1:
        S <- S + j^(n-1)
    return n * S

function MIN_RANGE_FOR_CONFIDENCE(n, epsilon):
    require epsilon > 0
    return ceil(n / epsilon)   // guarantees R(n, d) >= 1 - epsilon

function TELESCOPING_FENCE(n, d):
    lower <- d^n - n * d^(n-1)
    count <- n * sum_{j=0}^{d-1} j^(n-1)
    upper <- d^n
    assert lower <= count <= upper
    return (lower, count, upper)
